const h = require("/testbed/lib/eslint/eslint-helpers");
const { Linter } = require("/testbed/lib/linter");
const { FlatConfigArray } = require("/testbed/lib/config/flat-config-array");
const { WarningService } = require("/testbed/lib/services/warning-service");
const path = require("node:path");
const os = require("node:os");
const fs = require("node:fs");

(async () => {
  const dir = fs.mkdtempSync(path.join(os.tmpdir(), "eslint-probe3-"));
  const configs = new FlatConfigArray([{ files: ["**/*.js"], rules: { semi: ["error", "always"] } }], { basePath: dir });
  await configs.normalize();
  const linter = new Linter({ configType: "flat", cwd: dir });
  const r = h.verifyText({ text: "var a=1\n", cwd: dir, filePath: path.join(dir, "a.js"), configs, fix: false, allowInlineConfig: true, ruleFilter: () => true, stats: false, linter });
  console.log("verifyText", r.filePath, r.errorCount, r.source, r.messages.length);
  const r2 = h.verifyText({ text: "var a=1\n", cwd: dir, filePath: undefined, configs, fix: false, allowInlineConfig: true, ruleFilter: () => true, stats: true, linter });
  console.log("verifyText text", r2.filePath, Object.keys(r2.stats));
  const r3 = h.verifyText({ text: "var a=1\n", cwd: dir, filePath: path.join(dir, "a.js"), configs, fix: true, allowInlineConfig: true, ruleFilter: () => true, stats: false, linter });
  console.log("verifyText fix", r3.output);

  const fixer = h.getFixerForFixTypes(true, new Set(["layout"]), configs.getConfig(path.join(dir, "a.js")));
  console.log("fixer layout", typeof fixer, fixer({ ruleId: "semi", severity: 2 }));
  console.log("fixer null", h.getFixerForFixTypes(false, null, {}));
  const fixer2 = h.getFixerForFixTypes(() => "x", new Set(["problem"]), configs.getConfig(path.join(dir, "a.js")));
  console.log("fixer2", fixer2({ ruleId: "semi" }), fixer2({ ruleId: null }));

  // createLinter/createDefaultConfigs/createConfigLoader
  const ws = new WarningService();
  const l = h.createLinter(h.processOptions({ cwd: dir }), ws);
  console.log("createLinter", l.constructor.name, l.hasFlag("x"));
  console.log("defaultConfigs empty", h.createDefaultConfigs(undefined));
  const dcs = h.createDefaultConfigs({ "eslint-plugin-foo": { rules: {} }, bar: {} });
  console.log("defaultConfigs", JSON.stringify(Object.keys(dcs[0].plugins)));
  const cl = h.createConfigLoader(h.processOptions({ cwd: dir, overrideConfigFile: true }), [], l, ws);
  console.log("configLoader", cl.constructor.name);
  const clConfigs = await cl.loadConfigArrayForFile(path.join(dir, "a.js"));
  console.log("loaded config", !!clConfigs.getConfig(path.join(dir, "a.js")), clConfigs.isFileIgnored(path.join(dir, "a.js")));

  // findFiles
  fs.writeFileSync(path.join(dir, "a.js"), "var a=1\n");
  fs.writeFileSync(path.join(dir, "b.js"), "var b=2;\n");
  fs.mkdirSync(path.join(dir, "sub"));
  fs.writeFileSync(path.join(dir, "sub", "c.js"), "var c=3\n");
  const files = await h.findFiles({ patterns: ["*.js"], globInputPaths: true, cwd: dir, configLoader: cl, errorOnUnmatchedPattern: true });
  console.log("findFiles glob", files.map(f => path.relative(dir, f)));
  const files2 = await h.findFiles({ patterns: ["."], globInputPaths: true, cwd: dir, configLoader: cl, errorOnUnmatchedPattern: true });
  console.log("findFiles dot", files2.map(f => path.relative(dir, f)));
  const files3 = await h.findFiles({ patterns: ["a.js", "sub"], globInputPaths: true, cwd: dir, configLoader: cl, errorOnUnmatchedPattern: true });
  console.log("findFiles explicit", files3.map(f => path.relative(dir, f)));
  try { await h.findFiles({ patterns: ["missing.js"], globInputPaths: true, cwd: dir, configLoader: cl, errorOnUnmatchedPattern: true }); } catch (e) { console.log("nofiles", e.message, e.messageTemplate, JSON.stringify(e.messageData)); }
  try { await h.findFiles({ patterns: ["missing*.js"], globInputPaths: true, cwd: dir, configLoader: cl, errorOnUnmatchedPattern: true }); } catch (e) { console.log("noglobfiles", e.message, e.messageTemplate); }
  const empty = await h.findFiles({ patterns: ["missing.js"], globInputPaths: true, cwd: dir, configLoader: cl, errorOnUnmatchedPattern: false });
  console.log("findFiles no error", empty);
})().catch(e => { console.error("ERR", e); process.exit(1); });
