const { ESLint } = require("/testbed/lib/eslint");
const { pathToFileURL } = require("node:url");
const path = require("node:path");
const os = require("node:os");
const fs = require("node:fs");

(async () => {
  const dir = fs.mkdtempSync(path.join(os.tmpdir(), "eslint-probe6-"));
  for (const n of ["a", "b", "c", "d"]) fs.writeFileSync(path.join(dir, n + ".js"), n === "a" ? "var x=1\n" : "var y=2;\n");
  const eslint = new ESLint({ cwd: dir, overrideConfigFile: true, overrideConfig: { rules: { semi: "error" } }, concurrency: 2 });
  const results = await eslint.lintFiles(["*.js"]);
  console.log("concurrent", results.map(r => [path.basename(r.filePath), r.errorCount]));

  // uncloneable options
  try {
    new ESLint({ cwd: dir, concurrency: 2, ruleFilter: () => true, overrideConfigFile: true });
  } catch (e) { console.log("uncloneable", e.code, e.message); }

  // options module
  const modPath = path.join(dir, "eslint.options.mjs");
  fs.writeFileSync(modPath, `export default { cwd: ${JSON.stringify(dir)}, overrideConfigFile: true, overrideConfig: { rules: { semi: "error" } }, concurrency: 2, ruleFilter: () => true };\n`);
  const e2 = await ESLint.fromOptionsModule(pathToFileURL(modPath));
  const r2 = await e2.lintFiles(["*.js"]);
  console.log("modResults", r2.map(r => [path.basename(r.filePath), r.errorCount]));
  try { await ESLint.fromOptionsModule("not a url"); } catch (e) { console.log("badurl", e.constructor.name, e.message); }

  // lintFiles validation
  for (const p of [null, 1, [""], "  ", []]) {
    try { const r = await eslint.lintFiles(p); console.log("patterns", JSON.stringify(p), "->", r.length); } catch (e) { console.log("patterns err", JSON.stringify(p), e.message); }
  }
  const e3 = new ESLint({ cwd: dir, overrideConfigFile: true, passOnNoPatterns: true });
  console.log("passOnNoPatterns", await e3.lintFiles([]));

  // cache file deletion when cache disabled
  const cachePath = path.join(dir, ".eslintcache2");
  fs.writeFileSync(cachePath, "stale");
  const e4 = new ESLint({ cwd: dir, overrideConfigFile: true, cacheLocation: cachePath, overrideConfig: {} });
  await e4.lintFiles(["a.js"]);
  console.log("cache deleted?", fs.existsSync(cachePath));
  const e5 = new ESLint({ cwd: dir, overrideConfigFile: true, cache: true, cacheLocation: cachePath, overrideConfig: { rules: { semi: "error" } } });
  await e5.lintFiles(["a.js"]);
  console.log("cache created?", fs.existsSync(cachePath));
})().catch(e => { console.error("ERR", e); process.exit(1); });
EOF
