const { Worker } = require("node:worker_threads");
const { pathToFileURL } = require("node:url");
const path = require("node:path");
const os = require("node:os");
const fs = require("node:fs");

(async () => {
  const dir = fs.mkdtempSync(path.join(os.tmpdir(), "eslint-probe11-"));
  fs.writeFileSync(path.join(dir, "a.js"), "var a=1\n");
  const modPath = path.join(dir, "opts.mjs");
  fs.writeFileSync(modPath, `export default { cwd: ${JSON.stringify(dir)}, overrideConfigFile: true, overrideConfig: { rules: { semi: "error" } } };\n`);
  const run = (eslintOptionsOrURL, filePaths) => new Promise((resolve, reject) => {
    const worker = new Worker("/testbed/lib/eslint/worker.js", {
      workerData: { eslintOptionsOrURL, filePathIndexArray: new Uint32Array(new SharedArrayBuffer(4)), filePaths },
    });
    worker.once("message", m => { resolve(m); worker.terminate(); });
    worker.once("error", reject);
  });
  const m = await run(pathToFileURL(modPath).href, [path.join(dir, "a.js")]);
  console.log("url mode", m.length, m[0].errorCount, typeof m.netLintingDuration);

  // multiple files with 2 workers sharing one index array
  for (const n of ["b", "c", "d"]) fs.writeFileSync(path.join(dir, n + ".js"), "var z=1\n");
  const files = ["a.js","b.js","c.js","d.js"].map(f => path.join(dir, f));
  const sab = new Uint32Array(new SharedArrayBuffer(4));
  const runW = () => new Promise((resolve, reject) => {
    const w = new Worker("/testbed/lib/eslint/worker.js", { workerData: { eslintOptionsOrURL: { cwd: dir, overrideConfigFile: true, overrideConfig: { rules: { semi: "error" } } }, filePathIndexArray: sab, filePaths: files } });
    w.once("message", m => { resolve(m); w.terminate(); });
    w.once("error", reject);
  });
  const [m1, m2] = await Promise.all([runW(), runW()]);
  const all = [...m1, ...m2].map(r => path.basename(r.filePath)).sort();
  console.log("shared", all, "counter", Atomics.load(sab, 0));
  // cache in worker
  const cachePath = path.join(dir, ".cache");
  const m3 = await run({ cwd: dir, overrideConfigFile: true, overrideConfig: { rules: { semi: "error" } }, cache: true, cacheLocation: cachePath }, files);
  console.log("worker cache file", fs.existsSync(cachePath), m3.length);
})().catch(e => { console.error("ERR", e); process.exit(1); });
