 */
function createLoader(cwd, options = {}) {
	const warningService = new WarningService();
	const processedOptions = processOptions({
		cwd,
		overrideConfigFile: true,
		...options,
	});
	const linter = createLinter(processedOptions, warningService);
	const configLoader = createConfigLoader(
		processedOptions,
		createDefaultConfigs(options.plugins),
		linter,
		warningService,
	);

	return { processedOptions, linter, configLoader };
