		);
	});

	test("passes through a config file path", () => {
		expect(
			processOptions({ overrideConfigFile: "/some/eslint.config.js" })
				.configFile,
		).toBe("/some/eslint.config.js");
	});

	test("accepts a fix function, a ruleFilter and null plugins", () => {
		const fix = () => true;
		const ruleFilter = () => false;
		const options = processOptions({ fix, ruleFilter, plugins: null });

		expect(options.fix).toBe(fix);
		expect(options.ruleFilter).toBe(ruleFilter);
		expect(options.plugins).toBeNull();
	});

	test("reports unknown options and removed option replacements", () => {
		let error;

		try {
			processOptions({
				bogusOption: true,
				cacheFile: "cache.json",
				configFile: "config.js",
				rules: {},
			});
		} catch (caught) {
			error = caught;
		}

		expect(error).toBeInstanceOf(Error);
		expect(error.code).toBe("ESLINT_INVALID_OPTIONS");
		expect(error.message).toContain(
			"Unknown options: bogusOption, cacheFile, configFile, rules",
		);
		expect(error.message).toContain(
			"'cacheFile' has been removed. Please use the 'cacheLocation' option instead.",
		);
		expect(error.message).toContain(
			"'configFile' has been removed. Please use the 'overrideConfigFile' option instead.",
		);
		expect(error.message).toContain(
			"'rules' has been removed. Please use the 'overrideConfig.rules' option instead.",
		);
	});

	test.each([
		[{ allowInlineConfig: "yes" }, "'allowInlineConfig' must be a boolean."],
		[{ baseConfig: "config" }, "'baseConfig' must be an object or null."],
		[{ cache: "yes" }, "'cache' must be a boolean."],
		[{ cacheLocation: "" }, "'cacheLocation' must be a non-empty string."],
		[
			{ cacheStrategy: "invalid" },
			'\'cacheStrategy\' must be any of "metadata", "content".',
		],
		[
			{ concurrency: 0 },
			'\'concurrency\' must be a positive integer, "auto", or "off".',
		],
		[{ cwd: "relative" }, "'cwd' must be an absolute path."],
		[
			{ errorOnUnmatchedPattern: "yes" },
			"'errorOnUnmatchedPattern' must be a boolean.",
		],
		[{ fix: "yes" }, "'fix' must be a boolean or a function."],
		[
			{ fixTypes: ["invalid"] },
			'\'fixTypes\' must be an array of any of "directive", "problem", "suggestion", and "layout".',
		],
		[{ flags: [""] }, "'flags' must be an array of non-empty strings."],
		[{ globInputPaths: "yes" }, "'globInputPaths' must be a boolean."],
		[{ ignore: "yes" }, "'ignore' must be a boolean."],
		[
			{ ignorePatterns: "node_modules" },
			"'ignorePatterns' must be an array of non-empty strings or null.",
		],
		[{ overrideConfig: "config" }, "'overrideConfig' must be an object or null."],
		[
			{ overrideConfigFile: false },
			"'overrideConfigFile' must be a non-empty string, null, or true.",
		],
		[
			{ passOnNoPatterns: "yes" },
			"'passOnNoPatterns' must be a boolean.",
		],
		[{ plugins: "plugin" }, "'plugins' must be an object or null."],
		[{ plugins: { "": {} } }, "'plugins' must not include an empty string."],
		[
			{ plugins: [] },
			"'plugins' doesn't add plugins to configuration to load. Please use the 'overrideConfig.plugins' option instead.",
		],
		[{ stats: "yes" }, "'stats' must be a boolean."],
		[{ warnIgnored: "yes" }, "'warnIgnored' must be a boolean."],
		[{ ruleFilter: "yes" }, "'ruleFilter' must be a function."],
		[
			{ applySuppressions: "yes" },
			"'applySuppressions' must be a boolean.",
		],
		[
			{ suppressionsLocation: "" },
			"'suppressionsLocation' must be a non-empty string.",
		],
	])("rejects invalid option %j", (options, expectedMessage) => {
		expect(() => processOptions(options)).toThrow(expectedMessage);
	});

	test("throws an error whose code identifies invalid options", () => {
		expect(() => processOptions({ cache: "yes" })).toThrow(
			expect.objectContaining({ code: "ESLINT_INVALID_OPTIONS" }),
		);
	});
});

