	createLintResultCache,
	getFixerForFixTypes,
	verifyText,
	lintFile,
	findFiles,
	createLinter,
	createDefaultConfigs,
	createConfigLoader,
} = helpers;

const tempDirs = [];

/**
 * Creates a temporary directory that is removed after each test.
 * @returns {string} The absolute path of the new directory.
 */
function makeTempDir() {
	const dir = fs.mkdtempSync(path.join(os.tmpdir(), "eslint-helpers-test-"));
	tempDirs.push(dir);
	return dir;
}

/**
 * Creates a config loader using the same helpers as the ESLint class.
 * @param {string} cwd The working directory.
 * @param {Object} [options] Additional ESLint options.
 * @returns {Object} The processed options, linter, and config loader.
 */
function createLoader(cwd, options = {}) {
	const warningService = new WarningService();
	const processedOptions = processOptions({
		cwd,
		overrideConfigFile: true,
		...options,
	});
	const linter = createLinter(processedOptions, warningService);
	const configLoader = createConfigLoader(
		processedOptions,
		createDefaultConfigs(options.plugins),
		linter,
		warningService,
	);

	return { processedOptions, linter, configLoader };
}

/**
 * Creates a normalized flat config array for a directory.
 * @param {string} basePath The base path of the config array.
 * @param {Object} [config] A config object to include.
 * @returns {Promise<FlatConfigArray>} The normalized config array.
 */
async function makeConfigs(basePath, config = {}) {
	const configs = new FlatConfigArray([{ files: ["**/*.js"], ...config }], {
		basePath,
	});

	await configs.normalize();
	return configs;
}

