describe("getFixerForFixTypes()", () => {
	const cwd = path.join(path.sep, "some", "dir");
	let config;

	beforeEach(async () => {
		config = (await makeConfigs(cwd)).getConfig(
			path.join(cwd, "file.js"),
		);
	});

	test("returns the original fix value when fix is falsy", () => {
		expect(getFixerForFixTypes(false, new Set(["layout"]), config)).toBe(
			false,
		);
		expect(getFixerForFixTypes(void 0, new Set(["layout"]), config)).toBe(
			void 0,
		);
	});

	test("returns the original fix value when no fix types are given", () => {
		expect(getFixerForFixTypes(true, null, config)).toBe(true);
	});

	test("only allows messages whose rule type is selected", () => {
		const fixer = getFixerForFixTypes(true, new Set(["layout"]), config);

		expect(fixer({ ruleId: "semi", severity: 2 })).toBe(true);
	});

	test("rejects messages whose rule type is not selected", () => {
		const fixer = getFixerForFixTypes(true, new Set(["problem"]), config);

		expect(fixer({ ruleId: "semi", severity: 2 })).toBe(false);
	});

	test("allows directive messages only when 'directive' is selected", () => {
		const directiveFixer = getFixerForFixTypes(
			true,
			new Set(["directive"]),
			config,
		);
		const otherFixer = getFixerForFixTypes(
			true,
			new Set(["layout"]),
			config,
		);

		expect(directiveFixer({ ruleId: null, severity: 2 })).toBe(true);
		expect(otherFixer({ ruleId: null, severity: 2 })).toBe(false);
	});

	test("combines the fix type filter with a custom fix function", () => {
		const fix = jest.fn(() => true);
		const fixer = getFixerForFixTypes(fix, new Set(["layout"]), config);

		expect(fixer({ ruleId: "semi", severity: 2 })).toBe(true);
		expect(fix).toHaveBeenCalledTimes(1);
		expect(fixer({ ruleId: "no-undef", severity: 2 })).toBe(false);
		expect(fix).toHaveBeenCalledTimes(1);
	});

	test("rejects unknown rule ids", () => {
		const fixer = getFixerForFixTypes(true, new Set(["layout"]), config);

		expect(fixer({ ruleId: "not-a-rule", severity: 2 })).toBe(false);
	});
});

