		);

		expect(result.warningCount).toBe(1);
		expect(result.messages[0].message).toContain(
			"matching ignore pattern",
		);
	});

	test("returns undefined for an ignored file when warnIgnored is false", async () => {
		const ignoreLoader = createLoader(cwd, {
			warnIgnored: false,
			overrideConfig: { ignores: ["file.js"], rules: { semi: "error" } },
		});
		const configs =
			await ignoreLoader.configLoader.loadConfigArrayForFile(filePath);
		const result = await lintFile(
			filePath,
			configs,
			ignoreLoader.processedOptions,
			ignoreLoader.linter,
			null,
			null,
		);

		expect(result).toBeUndefined();
	});

	test("uses a cached result when one is available", async () => {
		const cacheFilePath = path.join(cwd, ".eslintcache");
		const cache = createLintResultCache(
			{ cache: true, cacheStrategy: "metadata" },
			cacheFilePath,
		);
		const configs = await loader.configLoader.loadConfigArrayForFile(
			filePath,
		);
		const config = configs.getConfig(filePath);
		const stat = fs.statSync(filePath);

		const firstResult = await lintFile(
			filePath,
			configs,
			loader.processedOptions,
			loader.linter,
			cache,
			null,
		);

		cache.setCachedLintResults(filePath, config, firstResult);

		// same size, same mtime, different content: a cache hit hides the change
		fs.writeFileSync(filePath, "var a = 1;");
		fs.utimesSync(filePath, stat.atime, stat.mtime);

		const secondResult = await lintFile(
			filePath,
			configs,
			loader.processedOptions,
			loader.linter,
			cache,
			null,
		);

		expect(secondResult.errorCount).toBe(1);
	});

	test("accumulates read time in the read file counter", async () => {
		const configs = await loader.configLoader.loadConfigArrayForFile(
			filePath,
		);
		const readFileCounter = { duration: 0n };

		await lintFile(
			filePath,
			configs,
			loader.processedOptions,
			loader.linter,
			null,
			readFileCounter,
		);

		expect(typeof readFileCounter.duration).toBe("bigint");
		expect(readFileCounter.duration).toBeGreaterThan(0n);
	});

	test("rejects when the file cannot be read", async () => {
		const missingFile = path.join(cwd, "missing.js");
		const configs =
			await loader.configLoader.loadConfigArrayForFile(missingFile);

		await expect(
			lintFile(
				missingFile,
				configs,
				loader.processedOptions,
				loader.linter,
				null,
				null,
			),
		).rejects.toThrow(/ENOENT/u);
	});
});

describe("findFiles()", () => {
	let cwd;
	let configLoader;

	beforeEach(() => {
		cwd = makeTempDir();
		fs.writeFileSync(path.join(cwd, "a.js"), "var a = 1;\n");
		fs.writeFileSync(path.join(cwd, "b.js"), "var b = 2;\n");
		fs.mkdirSync(path.join(cwd, "sub"));
		fs.writeFileSync(path.join(cwd, "sub", "c.js"), "var c = 3;\n");
		configLoader = createLoader(cwd).configLoader;
	});

	/**
	 * Finds files relative to the temporary directory.
	 * @param {string[]} patterns Patterns to find.
	 * @param {Object} [extra] Extra options.
	 * @returns {Promise<string[]>} Relative file paths.
	 */
	async function find(patterns, extra = {}) {
		const files = await findFiles({
			patterns,
			globInputPaths: true,
			cwd,
			configLoader,
			errorOnUnmatchedPattern: true,
			...extra,
		});

		return files.map(filePath => path.relative(cwd, filePath)).sort();
	}

	test("finds files matching a glob", async () => {
		expect(await find(["*.js"])).toEqual(["a.js", "b.js"]);
	});

	test("finds all files in a directory recursively", async () => {
		expect(await find(["."])).toEqual(["a.js", "b.js", "sub/c.js"]);
	});

	test("finds explicit files and directories", async () => {
		expect(await find(["b.js", "sub"])).toEqual(["b.js", "sub/c.js"]);
	});

	test("deduplicates files matched by multiple patterns", async () => {
		expect(await find(["a.js", "a.js", "*.js"])).toEqual([
			"a.js",
			"b.js",
		]);
	});

	test("throws when an explicit file does not exist", async () => {
		await expect(find(["missing.js"])).rejects.toMatchObject({
			messageTemplate: "file-not-found",
			messageData: { pattern: "missing.js", globDisabled: false },
			message: "No files matching 'missing.js' were found.",
		});
	});

	test("throws when a glob does not match anything", async () => {
		await expect(find(["missing*.js"])).rejects.toThrow(
			"No files matching 'missing*.js' were found.",
		);
	});

	test("reports disabled globs in the error message", async () => {
		await expect(
			find(["*.js"], { globInputPaths: false }),
		).rejects.toMatchObject({
			messageTemplate: "file-not-found",
			messageData: { pattern: "*.js", globDisabled: true },
			message:
				"No files matching '*.js' were found (glob was disabled).",
		});
	});

	test("does not throw for unmatched patterns when disabled", async () => {
		expect(
			await find(["missing.js"], { errorOnUnmatchedPattern: false }),
		).toEqual([]);
	});

	test("returns files that match when only some patterns are unmatched", async () => {
		expect(
			await find(["a.js", "missing.js"], {
				errorOnUnmatchedPattern: false,
			}),
		).toEqual(["a.js"]);
	});

	test("throws an 'all files ignored' error when every match is ignored", async () => {
		const ignoreLoader = createLoader(cwd, {
			overrideConfig: { ignores: ["*.js"], rules: { semi: "error" } },
		});

		await expect(
			findFiles({
				patterns: ["*.js"],
				globInputPaths: true,
				cwd,
				configLoader: ignoreLoader.configLoader,
				errorOnUnmatchedPattern: true,
			}),
		).rejects.toMatchObject({
			messageTemplate: "all-matched-files-ignored",
			messageData: { pattern: "*.js" },
			message: "All files matched by '*.js' are ignored.",
		});
	});

	test("returns an empty array when no patterns are given", async () => {
		await expect(find([])).resolves.toEqual([]);
	});

	test("finds files outside of the cwd", async () => {
		const outsideDir = makeTempDir();

		fs.writeFileSync(path.join(outsideDir, "outside.js"), "var d = 4;\n");

		const files = await findFiles({
			patterns: [path.join(outsideDir, "*.js")],
			globInputPaths: true,
			cwd,
			configLoader,
			errorOnUnmatchedPattern: true,
		});

		expect(files).toEqual([path.join(outsideDir, "outside.js")]);
	});
});

