/**
 * @fileoverview Tests for the public ESLint API in lib/eslint/eslint.js
 */

"use strict";

jest.setTimeout(30000);

const path = require("node:path");
const os = require("node:os");
const fs = require("node:fs");
const { pathToFileURL } = require("node:url");

const { ESLint } = require("../../../lib/eslint");
const { defaultConfig } = require("../../../lib/config/default-config");
const { version } = require("../../../package.json");

const tempDirs = [];

/**
 * Creates a temporary directory that is removed after each test.
 * @returns {string} The absolute path of the new directory.
 */
function makeTempDir() {
	const dir = fs.mkdtempSync(path.join(os.tmpdir(), "eslint-api-test-"));
	tempDirs.push(dir);
	return dir;
}

/**
 * Writes a file, creating parent directories as needed.
 * @param {string} dir The base directory.
 * @param {string} relativePath The path relative to `dir`.
 * @param {string} contents The file contents.
 * @returns {string} The absolute path of the written file.
 */
function writeFile(dir, relativePath, contents) {
	const filePath = path.join(dir, relativePath);

	fs.mkdirSync(path.dirname(filePath), { recursive: true });
	fs.writeFileSync(filePath, contents);
	return filePath;
}

/**
 * Creates an ESLint instance that does not look for a config file.
 * @param {string} cwd The working directory.
 * @param {Object} [options] Additional options.
 * @returns {ESLint} The new instance.
 */
function makeESLint(cwd, options = {}) {
	return new ESLint({ cwd, overrideConfigFile: true, ...options });
}

let spyOnWarnings;

beforeEach(() => {
	// ESLint emits process warnings for some conditions; keep test output clean
	// while still allowing individual tests to assert on them.
	if (!spyOnWarnings) {
		spyOnWarnings = jest
			.spyOn(process, "emitWarning")
			.mockImplementation(() => {});
	}
	spyOnWarnings.mockClear();
});

afterEach(() => {
	while (tempDirs.length) {
		fs.rmSync(tempDirs.pop(), { recursive: true, force: true });
	}
});

afterAll(() => {
	spyOnWarnings.mockRestore();
});

describe("static properties", () => {
	test("configType is 'flat'", () => {
		expect(ESLint.configType).toBe("flat");
	});

	test("version matches the package version", () => {
		expect(ESLint.version).toBe(version);
	});

	test("defaultConfig is the shared default config", () => {
		expect(ESLint.defaultConfig).toBe(defaultConfig);
	});
});

describe("constructor", () => {
	test("throws for invalid options", () => {
		expect(() => new ESLint({ concurrency: 0 })).toThrow(
			expect.objectContaining({ code: "ESLINT_INVALID_OPTIONS" }),
		);
	});

	test("warns when an .eslintignore file is present", () => {
		const dir = makeTempDir();

		writeFile(dir, ".eslintignore", "ignored.js\n");

		makeESLint(dir);

		expect(spyOnWarnings).toHaveBeenCalledWith(
			expect.stringContaining(".eslintignore"),
			"ESLintIgnoreWarning",
		);
	});

	test("does not warn about .eslintignore when the file is absent", () => {
		const dir = makeTempDir();

		makeESLint(dir);

		expect(spyOnWarnings).not.toHaveBeenCalled();
	});
});

describe("feature flags", () => {
	test("hasFlag() is false for flags that were not enabled", () => {
		const eslint = makeESLint(makeTempDir());

		expect(eslint.hasFlag("test_only")).toBe(false);
		expect(eslint.hasFlag("unstable_native_nodejs_ts_config")).toBe(false);
	});

	test("hasFlag() is true for flags passed to the constructor", () => {
		const eslint = makeESLint(makeTempDir(), {
			flags: ["test_only", "test_only_2"],
		});

		expect(eslint.hasFlag("test_only")).toBe(true);
		expect(eslint.hasFlag("test_only_2")).toBe(true);
	});

	test("throws for unknown flags", () => {
		expect(
			() => makeESLint(makeTempDir(), { flags: ["not_a_flag"] }),
		).toThrow("Unknown flag 'not_a_flag'.");
	});

	test("replaced flags emit a warning and enable the replacement", () => {
		const eslint = makeESLint(makeTempDir(), {
			flags: ["test_only_replaced"],
		});

		expect(eslint.hasFlag("test_only_replaced")).toBe(false);
		expect(eslint.hasFlag("test_only")).toBe(true);
		expect(spyOnWarnings).toHaveBeenCalledWith(
			expect.stringContaining("The flag 'test_only_replaced' is inactive"),
			"ESLintInactiveFlag_test_only_replaced",
		);
	});

	test("merges flags from the ESLINT_FLAGS environment variable", () => {
		const originalFlags = process.env.ESLINT_FLAGS;

		process.env.ESLINT_FLAGS = "test_only_2, test_only";

		try {
			const eslint = makeESLint(makeTempDir(), {
				flags: ["test_only"],
