			() => makeESLint(makeTempDir(), { flags: ["not_a_flag"] }),
		).toThrow("Unknown flag 'not_a_flag'.");
	});

	test("replaced flags emit a warning and enable the replacement", () => {
		const eslint = makeESLint(makeTempDir(), {
			flags: ["test_only_replaced"],
		});

		expect(eslint.hasFlag("test_only_replaced")).toBe(false);
		expect(eslint.hasFlag("test_only")).toBe(true);
		expect(spyOnWarnings).toHaveBeenCalledWith(
			expect.stringContaining("The flag 'test_only_replaced' is inactive"),
			"ESLintInactiveFlag_test_only_replaced",
		);
	});

	test("merges flags from the ESLINT_FLAGS environment variable", () => {
		const originalFlags = process.env.ESLINT_FLAGS;

		process.env.ESLINT_FLAGS = "test_only_2, test_only";

		try {
			const eslint = makeESLint(makeTempDir(), {
				flags: ["test_only"],
			});

			expect(eslint.hasFlag("test_only")).toBe(true);
			expect(eslint.hasFlag("test_only_2")).toBe(true);
		} finally {
			if (originalFlags === void 0) {
				delete process.env.ESLINT_FLAGS;
			} else {
				process.env.ESLINT_FLAGS = originalFlags;
			}
		}
	});
});

describe("concurrency options", () => {
	test("rejects uncloneable options when concurrency is enabled", () => {
		expect(
			() =>
				new ESLint({
					cwd: makeTempDir(),
					overrideConfigFile: true,
					concurrency: 2,
					ruleFilter: () => true,
				}),
		).toThrow(
			expect.objectContaining({
				code: "ESLINT_UNCLONEABLE_OPTIONS",
				message: expect.stringContaining('The option "ruleFilter"'),
			}),
		);
	});

	test("lists all uncloneable options in the error message", () => {
		expect(
			() =>
				new ESLint({
					cwd: makeTempDir(),
					overrideConfigFile: true,
					concurrency: 2,
					fix: () => true,
					ruleFilter: () => true,
				}),
		).toThrow(
			expect.objectContaining({
				code: "ESLINT_UNCLONEABLE_OPTIONS",
				message: expect.stringContaining('options "fix", "ruleFilter"'),
			}),
		);
	});

	test("allows uncloneable options when concurrency is off", () => {
		expect(
			() =>
				new ESLint({
					cwd: makeTempDir(),
					overrideConfigFile: true,
					ruleFilter: () => true,
				}),
		).not.toThrow();
	});

	test("lints files in multiple worker threads", async () => {
		const dir = makeTempDir();

		writeFile(dir, "a.js", "var a = 1\n");
		writeFile(dir, "b.js", "var b = 2;\n");
		writeFile(dir, "c.js", "var c = 3\n");
		writeFile(dir, "d.js", "var d = 4;\n");

		const config = {
			overrideConfig: { rules: { semi: ["error", "always"] } },
		};
		const sequential = await makeESLint(dir, config).lintFiles(["*.js"]);
		const concurrent = await makeESLint(dir, {
			...config,
			concurrency: 2,
		}).lintFiles(["*.js"]);

		expect(
			concurrent.map(result => [
				path.basename(result.filePath),
				result.errorCount,
			]),
		).toEqual(
			sequential.map(result => [
				path.basename(result.filePath),
				result.errorCount,
			]),
		);
		expect(concurrent).toHaveLength(4);
		expect(
			concurrent.filter(result => result.errorCount === 1),
		).toHaveLength(2);
	});
});

