				errorCount: 0,
				warningCount: 1,
				fixableErrorCount: 0,
				fixableWarningCount: 1,
			},
		];

		const filtered = ESLint.getErrorResults(results);

		expect(filtered).toHaveLength(1);
		expect(filtered[0]).toMatchObject({
			filePath,
			errorCount: 1,
			warningCount: 0,
			fixableErrorCount: 1,
			fixableWarningCount: 0,
		});
