describe("calculateWorkerCount()", () => {
	/**
	 * Creates an ESLint instance and pre-loads configs for the given files.
	 * @param {string} cwd The working directory.
	 * @param {"off"|"auto"|number} concurrency The concurrency setting.
	 * @param {string[]} filePaths File paths to pre-load configs for.
	 * @returns {Promise<ESLint>} The ESLint instance.
	 */
	async function createInstance(cwd, concurrency, filePaths = []) {
		const eslint = new ESLint({ cwd, overrideConfigFile: true, concurrency });

		await Promise.all(
			filePaths.map(filePath =>
				eslint.calculateConfigForFile(filePath),
			),
		);
		return eslint;
	}

	/**
	 * Creates a directory with a number of JavaScript files.
	 * @param {number} count The number of files to create.
	 * @returns {{dir: string, filePaths: string[]}} The directory and file paths.
	 */
	function createFiles(count) {
		const dir = makeTempDir();
		const filePaths = [];

		for (let index = 0; index < count; index++) {
			const filePath = path.join(dir, `file-${index}.js`);

			fs.writeFileSync(filePath, "var a = 1;\n");
			filePaths.push(filePath);
		}

		return { dir, filePaths };
	}

	test("returns 0 when concurrency is off", async () => {
		const { dir, filePaths } = createFiles(5);
		const eslint = await createInstance(dir, "off", filePaths);

		expect(
			calculateWorkerCount(eslint, filePaths, {
				availableParallelism: () => 16,
			}),
		).toBe(0);
	});

	test("returns 0 when concurrency is 1", async () => {
		const { dir, filePaths } = createFiles(5);
		const eslint = await createInstance(dir, 1, filePaths);

		expect(
			calculateWorkerCount(eslint, filePaths, {
				availableParallelism: () => 16,
			}),
		).toBe(0);
	});

	test("caps the worker count at the number of files", async () => {
		const { dir, filePaths } = createFiles(2);
		const eslint = await createInstance(dir, 4, filePaths);

		expect(
			calculateWorkerCount(eslint, filePaths, {
				availableParallelism: () => 16,
			}),
		).toBe(2);
	});

	test("uses the configured concurrency when there are enough files", async () => {
		const { dir, filePaths } = createFiles(10);
		const eslint = await createInstance(dir, 4, filePaths);

		expect(
			calculateWorkerCount(eslint, filePaths, {
				availableParallelism: () => 16,
			}),
		).toBe(4);
	});

	test("returns 0 for auto concurrency when no files need processing", async () => {
		const { dir } = createFiles(0);
		const eslint = await createInstance(dir, "auto");

		expect(
			calculateWorkerCount(eslint, [], { availableParallelism: () => 8 }),
		).toBe(0);
	});

	test("returns 0 for auto concurrency with few files", async () => {
		const { dir, filePaths } = createFiles(50);
		const eslint = await createInstance(dir, "auto", filePaths);

		expect(
			calculateWorkerCount(eslint, filePaths, {
				availableParallelism: () => 8,
			}),
		).toBe(0);
	});

	test("returns 2 workers for auto concurrency starting at 51 files", async () => {
		const { dir, filePaths } = createFiles(51);
		const eslint = await createInstance(dir, "auto", filePaths);

		expect(
			calculateWorkerCount(eslint, filePaths, {
				availableParallelism: () => 8,
			}),
		).toBe(2);
	});

	test("caps auto concurrency at half of the available parallelism", async () => {
		const { dir, filePaths } = createFiles(120);
		const eslint = await createInstance(dir, "auto", filePaths);

		expect(
			calculateWorkerCount(eslint, filePaths, {
				availableParallelism: () => 4,
			}),
		).toBe(2);
	});

	test("returns 0 for auto concurrency when only one worker would be possible", async () => {
		const { dir, filePaths } = createFiles(120);
		const eslint = await createInstance(dir, "auto", filePaths);

		expect(
			calculateWorkerCount(eslint, filePaths, {
				availableParallelism: () => 2,
			}),
		).toBe(0);
	});
});
