/**
 * @fileoverview Tests for lib/eslint/worker.js
 */

"use strict";

jest.setTimeout(30000);

const path = require("node:path");
const os = require("node:os");
const fs = require("node:fs");
const { Worker } = require("node:worker_threads");
const { pathToFileURL } = require("node:url");

const WORKER_PATH = path.join(__dirname, "../../../lib/eslint/worker.js");

const tempDirs = [];

/**
 * Creates a temporary directory that is removed after each test.
 * @returns {string} The absolute path of the new directory.
 */
function makeTempDir() {
	const dir = fs.mkdtempSync(path.join(os.tmpdir(), "eslint-worker-test-"));
	tempDirs.push(dir);
	return dir;
}

/**
 * Creates a shared index array for worker threads.
 * @returns {Uint32Array} The shared counter.
 */
function createIndexArray() {
	return new Uint32Array(
		new SharedArrayBuffer(Uint32Array.BYTES_PER_ELEMENT),
	);
}

/**
 * Runs the ESLint worker thread.
 * @param {Object} workerData The data to pass to the worker.
 * @returns {Promise<Array>} The results posted by the worker.
 */
function runWorker(workerData) {
	return new Promise((resolve, reject) => {
		const worker = new Worker(WORKER_PATH, { workerData });

		worker.once("message", results => {
			resolve(results);
			worker.terminate();
		});
		worker.once("error", error => {
			reject(error);
			worker.terminate();
		});
	});
}

afterEach(() => {
	while (tempDirs.length) {
		fs.rmSync(tempDirs.pop(), { recursive: true, force: true });
	}
});

describe("worker thread", () => {
	test("lints the given files and posts indexed results", async () => {
		const dir = makeTempDir();
		const errorFile = path.join(dir, "error.js");
		const cleanFile = path.join(dir, "clean.js");

		fs.writeFileSync(errorFile, "var a = 1\n");
		fs.writeFileSync(cleanFile, "var b = 2;\n");

		const results = await runWorker({
			eslintOptionsOrURL: {
				cwd: dir,
				overrideConfigFile: true,
				overrideConfig: { rules: { semi: ["error", "always"] } },
			},
			filePathIndexArray: createIndexArray(),
			filePaths: [errorFile, cleanFile],
		});

		expect(results).toHaveLength(2);
		expect(typeof results.netLintingDuration).toBe("bigint");
		expect(results.netLintingDuration).toBeGreaterThanOrEqual(0n);

		const errorResult = results.find(
			result => result.filePath === errorFile,
		);
		const cleanResult = results.find(
			result => result.filePath === cleanFile,
		);

		expect(errorResult).toMatchObject({ index: 0, errorCount: 1 });
		expect(errorResult.messages[0].ruleId).toBe("semi");
		expect(cleanResult).toMatchObject({ index: 1, errorCount: 0 });
	});

	test("posts an empty result array when there is nothing to lint", async () => {
		const dir = makeTempDir();
		const results = await runWorker({
			eslintOptionsOrURL: {
				cwd: dir,
				overrideConfigFile: true,
			},
			filePathIndexArray: createIndexArray(),
			filePaths: [],
		});

		expect(results).toHaveLength(0);
		expect(typeof results.netLintingDuration).toBe("bigint");
	});

	test("loads options from an options module URL", async () => {
		const dir = makeTempDir();
		const filePath = path.join(dir, "file.js");
		const optionsPath = path.join(dir, "options.mjs");

		fs.writeFileSync(filePath, "var a = 1\n");
		fs.writeFileSync(
			optionsPath,
			`export default {
	cwd: ${JSON.stringify(dir)},
	overrideConfigFile: true,
	overrideConfig: { rules: { semi: "error" } }
};
`,
		);

		const results = await runWorker({
			eslintOptionsOrURL: pathToFileURL(optionsPath).href,
			filePathIndexArray: createIndexArray(),
			filePaths: [filePath],
		});

		expect(results).toHaveLength(1);
		expect(results[0].errorCount).toBe(1);
		expect(results[0].filePath).toBe(filePath);
	});

	test("returns a warning result for ignored files", async () => {
		const dir = makeTempDir();
		const filePath = path.join(dir, "ignored.js");

		fs.writeFileSync(filePath, "var a = 1\n");

		const results = await runWorker({
			eslintOptionsOrURL: {
				cwd: dir,
				overrideConfigFile: true,
				overrideConfig: [{ ignores: ["ignored.js"] }],
			},
			filePathIndexArray: createIndexArray(),
			filePaths: [filePath],
		});

		expect(results).toHaveLength(1);
		expect(results[0].warningCount).toBe(1);
		expect(results[0].messages[0].message).toContain(
			"matching ignore pattern",
		);
	});

	test("coordinates multiple workers through the shared index array", async () => {
		const dir = makeTempDir();
		const filePaths = ["a", "b", "c", "d"].map(name => {
			const filePath = path.join(dir, `${name}.js`);

			fs.writeFileSync(filePath, "var a = 1;\n");
			return filePath;
