		const indexArray = createIndexArray();
		const workerData = {
			eslintOptionsOrURL: {
				cwd: dir,
				overrideConfigFile: true,
				overrideConfig: { rules: { semi: "error" } },
			},
			filePathIndexArray: indexArray,
			filePaths,
		};

		const [firstResults, secondResults] = await Promise.all([
			runWorker(workerData),
			runWorker(workerData),
		]);
		const lintedPaths = [...firstResults, ...secondResults]
			.filter(Boolean)
			.map(result => result.filePath)
			.sort();

		expect(lintedPaths).toEqual([...filePaths].sort());
